package com.companion.persistence;
import org.junit.jupiter.api.Test;import org.springframework.core.io.ClassPathResource;import org.springframework.jdbc.datasource.init.ScriptUtils;import java.sql.*;import static org.assertj.core.api.Assertions.*;
class AgentCoreMigrationTest {@Test void createsCheckpointTablesAndUniqueness()throws Exception{String url="jdbc:h2:mem:agent_v27;MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1";try(Connection c=DriverManager.getConnection(url,"sa","");Statement s=c.createStatement()){ScriptUtils.executeSqlScript(c,new ClassPathResource("db/migration/V27__add_agent_core.sql"));s.executeUpdate("INSERT INTO t_agent_run(user_id,request_id,goal,status,create_time,update_time) VALUES(1,'r','g','PENDING',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)");try(ResultSet rs=s.executeQuery("SELECT execution_version FROM t_agent_run WHERE id=1")){assertThat(rs.next()).isTrue();assertThat(rs.getInt(1)).isZero();}assertThatThrownBy(()->s.executeUpdate("INSERT INTO t_agent_run(user_id,request_id,goal,status,create_time,update_time) VALUES(1,'r','g','PENDING',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)")).isInstanceOf(Exception.class);s.executeUpdate("INSERT INTO t_agent_step(run_id,step_number,tool_call_id,status,create_time,update_time) VALUES(1,1,'t','PENDING',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)");try(ResultSet rs=s.executeQuery("SELECT tool_attempt_count FROM t_agent_step WHERE id=1")){assertThat(rs.next()).isTrue();assertThat(rs.getInt(1)).isZero();}s.executeUpdate("UPDATE t_agent_step SET tool_attempt_count=1 WHERE id=1");s.executeUpdate("UPDATE t_agent_step SET tool_attempt_count=2 WHERE id=1");assertThatThrownBy(()->s.executeUpdate("UPDATE t_agent_step SET tool_attempt_count=3 WHERE id=1")).isInstanceOf(SQLException.class);assertThatThrownBy(()->s.executeUpdate("UPDATE t_agent_step SET tool_attempt_count=-1 WHERE id=1")).isInstanceOf(SQLException.class);assertThatThrownBy(()->s.executeUpdate("INSERT INTO t_agent_step(run_id,step_number,tool_call_id,status,create_time,update_time) VALUES(1,1,'x','PENDING',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)")).isInstanceOf(Exception.class);assertThatThrownBy(()->s.executeUpdate("INSERT INTO t_agent_step(run_id,step_number,tool_call_id,status,create_time,update_time) VALUES(1,2,'t','PENDING',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)")).isInstanceOf(Exception.class);}}
}
